css:
.odsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2530;
    background: linear-gradient(160deg, #eef1f5 0%, #e2e7ee 100%);
    border-radius: 18px;
}

.odsim-container * {
    box-sizing: border-box;
}

.odsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1b2735 0%, #2c3e50 55%, #37536e 100%);
    color: #f3f6fa;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(27, 39, 53, 0.32);
    border-bottom: 4px solid #e08a1e;
}

.odsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.odsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f4c98a;
    background: rgba(224, 138, 30, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.odsim-subtitle {
    margin: 0 auto;
    max-width: 790px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7dfe8;
}

.odsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.odsim-period-counter #currentDay,
.odsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1b2735;
}

.odsim-round-name {
    background: #d4dce6;
    color: #1b2735;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.odsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a23b1e;
    background: #fbe6dd;
    padding: 4px 12px;
    border-radius: 999px;
}

.odsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.odsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 39, 53, 0.06);
    border-top: 4px solid #37536e;
}

.odsim-card-recovery { border-top-color: #1f7a4d; }
.odsim-card-adoption { border-top-color: #2f6fb0; }
.odsim-card-sustain { border-top-color: #6a4fb0; }
.odsim-card-revenue { border-top-color: #e08a1e; }

.odsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #607284;
}

.odsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1b2735;
}

.odsim-card-recovery .odsim-value { color: #1f7a4d; }
.odsim-card-adoption .odsim-value { color: #2f6fb0; }
.odsim-card-sustain .odsim-value { color: #6a4fb0; }
.odsim-card-revenue .odsim-value { color: #c5760f; }

.odsim-sublabel {
    font-size: 0.76rem;
    color: #708395;
    line-height: 1.35;
}

.odsim-recovery-fail .odsim-value { color: #c0392b; }
.odsim-recovery-target .odsim-value { color: #1f7a4d; }

.odsim-budget-over { border-top-color: #c0392b; }
.odsim-budget-over .odsim-value { color: #c0392b; }

.odsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1b2735;
    color: #eef3f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 5px solid #e08a1e;
}

.odsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.odsim-budget-bar.odsim-budget-bar-over {
    background: #5c1f17;
    border-left-color: #c0392b;
}

.odsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e08a1e;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(27, 39, 53, 0.05);
}

.odsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.odsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1b2735;
    margin-bottom: 6px;
}

.odsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34465a;
}

.odsim-briefing-text strong { color: #1f7a4d; }
.odsim-briefing-text em { color: #a23b1e; font-style: italic; }

.odsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 39, 53, 0.06);
}

.odsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1b2735;
    border-bottom: 2px solid #e6ebf1;
    padding-bottom: 8px;
}

.odsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #26384b;
    margin: 14px 0 6px;
}

.odsim-container select,
.odsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcc8d4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f9fc;
    color: #1d2530;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.odsim-container select:focus,
.odsim-container input[type="number"]:focus {
    outline: none;
    border-color: #e08a1e;
    box-shadow: 0 0 0 3px rgba(224, 138, 30, 0.18);
}

.odsim-container select option {
    background-color: #ffffff;
    color: #1d2530;
}

.odsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e08a1e;
}

.odsim-range-readout,
.odsim-lever-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c3e50;
    margin-top: 6px;
}

.odsim-range-readout span:last-child,
.odsim-lever-readout span:nth-child(2),
.odsim-lever-readout span:nth-child(4) {
    color: #1f7a4d;
    font-weight: 800;
}

.odsim-lever-readout.odsim-lever-readout-over span:nth-child(4) {
    color: #c0392b;
}

.odsim-hint {
    font-size: 0.8rem;
    color: #708395;
    margin-top: 4px;
    line-height: 1.4;
}

.odsim-lever-group {
    background: #f4f7fa;
    border: 1px solid #dde4ec;
    border-radius: 10px;
    padding: 10px 14px;
    margin-top: 10px;
}

.odsim-lever-head {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    font-weight: 800;
    color: #5a6e82;
    margin-bottom: 6px;
}

.odsim-lever-group:nth-of-type(1) .odsim-lever-head { color: #2f6fb0; }
.odsim-lever-group:nth-of-type(2) .odsim-lever-head { color: #1f7a4d; }
.odsim-lever-group:nth-of-type(3) .odsim-lever-head { color: #6a4fb0; }

.odsim-check {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    font-weight: 600 !important;
    font-size: 0.9rem !important;
    color: #26384b !important;
    margin: 6px 0 !important;
    cursor: pointer;
}

.odsim-check input[type="checkbox"] {
    width: 17px;
    height: 17px;
    margin-top: 2px;
    flex: 0 0 17px;
    accent-color: #e08a1e;
    cursor: pointer;
}

.odsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.odsim-container .btn-primary {
    background: linear-gradient(135deg, #1f7a4d 0%, #2c3e50 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 122, 77, 0.26);
}

.odsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.odsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcc8d4;
    color: #607284;
}

.odsim-coach {
    background: #1b2735;
    color: #eef3f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(27, 39, 53, 0.24);
    border-left: 5px solid #e08a1e;
}

.odsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f4c98a;
    margin-bottom: 8px;
}

.odsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.odsim-coach-body strong { color: #7fd6a3; }
.odsim-coach-body em { color: #f6b59a; font-style: italic; }

.odsim-history,
.odsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d6dde6;
    box-shadow: 0 4px 14px rgba(27, 39, 53, 0.06);
}

.odsim-history h3,
.odsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1b2735;
}

.odsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #26384b;
}

.odsim-container table#usfHistoryTable th {
    background: #eaeef3;
    color: #1b2735;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d2dae3;
}

.odsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2f6;
}

.odsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7f9fc;
}

.odsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .odsim-container {
        padding: 14px;
    }
    .odsim-header h1 {
        font-size: 1.7rem;
    }
    .odsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .odsim-value {
        font-size: 2rem;
    }
    .odsim-clock {
        margin-left: 0;
    }
    .odsim-period-counter {
        font-size: 0.88rem;
    }
    .odsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .odsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, odsim) ---- */
.odsim-completion { padding: 8px 4px 4px; }
.odsim-cm-head { text-align: center; margin-bottom: 16px; }
.odsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.odsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.odsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.odsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.odsim-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.odsim-cm-no { background: rgba(192,86,31,0.12); color: #b0521f; border: 1px solid rgba(192,86,31,0.45); }
.odsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.odsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(47,111,176,0.08); border: 1px solid rgba(47,111,176,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.odsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2f6fb0; }
.odsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.odsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.odsim-cm-insights { margin: 0; padding-left: 20px; }
.odsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

