(function() {
    'use strict';

    class ODArchitectAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `OD Architect`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD; budget in $k).
            this.START_RECOVERY = 25;     // composite of error / response / resolution / CSAT
            this.TARGET_RECOVERY = 70;    // credible day-end-of-Q2 trajectory
            this.STRETCH_RECOVERY = 85;   // peer benchmark CSAT level
            this.BUDGET_CAP = 1500;       // $1,500k one-time change budget
            this.REVENUE_AT_RISK = 60;    // $60M across 3 at-risk accounts

            // Lever catalogue: id -> cost ($k) and family.
            this.LEVERS = {
                levStructOwner:    { cost: 250, family: `structural` },
                levProcessRedesign:{ cost: 300, family: `process` },
                levErp:            { cost: 450, family: `process` },
                levTraining:       { cost: 360, family: `people` },
                levCoaching:       { cost: 180, family: `people` },
                levRecognition:    { cost: 120, family: `people` }
            };

            // Concept truths.
            this.TRUE_ROOT = `structural`;
            this.TRUE_REINFORCING = `ownership`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    recovery: this.START_RECOVERY,
                    adoption: 12,
                    sustain: 10,
                    budgetUsed: 0,
                    revenueRetained: 0,
                    targetMissed: false,
                    paperCompliance: false,
                    overBudget: false,
                    recoveryHistory: [this.START_RECOVERY],
                    adoptionHistory: [12],
                    sustainHistory: [10],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    root: `structural`,
                    reinforcing: `ownership`,
                    rigor: 60,
                    levers: { levStructOwner: true, levProcessRedesign: true, levErp: false, levTraining: false, levCoaching: false, levRecognition: false },
                    link: `multicause`,
                    sequence: `structurefirst`,
                    change: 120,
                    indicators: `leadingowners`,
                    shock: `protect`,
                    adoption: `involve`,
                    refreeze: `embed`,
                    ceo: `honest`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        _readLevers(decisions) {
            const levers = {};
            Object.keys(this.LEVERS).forEach((id) => {
                const el = document.getElementById(id);
                if (el) levers[id] = !!el.checked;
                else if (decisions.levers && typeof decisions.levers[id] === `boolean`) levers[id] = decisions.levers[id];
                else levers[id] = false;
            });
            return levers;
        }

        _leverStats(levers) {
            let count = 0, cost = 0;
            const families = {};
            Object.keys(this.LEVERS).forEach((id) => {
                if (levers[id]) {
                    count += 1;
                    cost += this.LEVERS[id].cost;
                    families[this.LEVERS[id].family] = true;
                }
            });
            return { count: count, cost: cost, families: Object.keys(families).length };
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const reinf = document.getElementById(`reinforcingInput`);
                const rig = document.getElementById(`rigorInput`);
                if (root) decisions.root = root.value;
                if (reinf) decisions.reinforcing = reinf.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const levers = this._readLevers(decisions);
                decisions.levers = levers;
                const link = document.getElementById(`linkInput`);
                if (link) decisions.link = link.value;
                const stats = this._leverStats(levers);
                if (stats.count < 2) { warn(`warn_lever_min`); return false; }
                if (stats.count > 4) { warn(`warn_lever_max`); return false; }
                if (stats.families < 2) { warn(`warn_lever_families`); return false; }
            } else if (round === 3) {
                const seq = document.getElementById(`sequenceInput`);
                const ch = document.getElementById(`changeInput`);
                const ind = document.getElementById(`indicatorsInput`);
                const sh = document.getElementById(`shockInput`);
                if (seq) decisions.sequence = seq.value;
                if (ch) decisions.change = parseFloat(ch.value);
                if (ind) decisions.indicators = ind.value;
                if (sh) decisions.shock = sh.value;
                if (!Number.isFinite(decisions.change) || decisions.change < 0) {
                    warn(`warn_change_negative`); return false;
                }
            } else if (round === 4) {
                const ad = document.getElementById(`adoptionInput`);
                const rf = document.getElementById(`refreezeInput`);
                const ce = document.getElementById(`ceoInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ad) decisions.adoption = ad.value;
                if (rf) decisions.refreeze = rf.value;
                if (ce) decisions.ceo = ce.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: adoption = genuine buy-in; paper = coerced metric not backed by buy-in;
            // sustain = ability to refreeze and survive after the project; spend = budget usage.
            let adoptionDelta = 0, sustainDelta = 0, paperDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose before intervention: structure is the primary root cause (Common Error 1).
                if (d.root === this.TRUE_ROOT) {
                    adoptionDelta += 11; sustainDelta += 5; coachKey = `coach_r1_root_right`;
                } else if (d.root === `process`) {
                    adoptionDelta += 3; sustainDelta += 1; coachKey = `coach_r1_process`;
                } else if (d.root === `people`) {
                    adoptionDelta -= 8; sustainDelta -= 4; coachKey = `coach_r1_people`;
                } else {
                    adoptionDelta -= 12; sustainDelta -= 6; coachKey = `coach_r1_individuals`;
                }

                // Reinforcing cause beneath the 6.8% error rate is the orphaned, ownerless hand-off.
                if (d.reinforcing === this.TRUE_REINFORCING) {
                    adoptionDelta += 9; sustainDelta += 4;
                    if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_diag_sharp`;
                } else if (d.reinforcing === `erp`) {
                    adoptionDelta += 3;
                } else if (d.reinforcing === `skills`) {
                    adoptionDelta -= 6; coachKey = `coach_r1_skills`;
                } else {
                    adoptionDelta -= 10; sustainDelta -= 4; coachKey = `coach_r1_symptom`;
                }

                // Diagnostic rigour: tracing evidence to root cause before naming a fix.
                if (d.rigor >= 60) { adoptionDelta += 6; sustainDelta += 2; }
                else if (d.rigor <= 25) { adoptionDelta -= 8; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.reinforcing === this.TRUE_REINFORCING) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the intervention mix (Common Errors 1 & 3).
                const levers = d.levers || {};
                const stats = this._leverStats(levers);
                spend = stats.cost;

                const hasStruct = !!levers.levStructOwner;
                const hasProcess = !!levers.levProcessRedesign || !!levers.levErp;
                const peopleSet = (levers.levTraining ? 1 : 0) + (levers.levCoaching ? 1 : 0) + (levers.levRecognition ? 1 : 0);
                const peopleOnly = (stats.families === 1) && peopleSet > 0;

                if (peopleOnly) {
                    // The comfortable HR default — motivate people inside a broken system.
                    adoptionDelta -= 6; sustainDelta -= 6; paperDelta += 4; coachKey = `coach_r2_peopleonly`;
                } else if (hasStruct && hasProcess && stats.families >= 2) {
                    // Structure to own it + process to fix the flow = the concept-correct backbone.
                    adoptionDelta += 11; sustainDelta += 7; coachKey = `coach_r2_mix_strong`;
                    if (peopleSet > 0 && stats.families === 3) { adoptionDelta += 2; sustainDelta += 2; coachKey = `coach_r2_mix_full`; }
                } else if (stats.families >= 2) {
                    adoptionDelta += 6; sustainDelta += 3; coachKey = `coach_r2_mix_partial`;
                } else {
                    adoptionDelta += 1;
                }

                // A single-lever fix can't close a multi-cause gap; chasing the visible metric is Error 1.
                switch (d.link) {
                    case `multicause`:  adoptionDelta += 6; sustainDelta += 4; break;
                    case `singlelever`: adoptionDelta -= 8; sustainDelta -= 4; coachKey = `coach_r2_singlelever`; break;
                    case `visible`:     adoptionDelta -= 6; paperDelta += 5; coachKey = `coach_r2_visible`; break;
                }

                // Missing the structural lever entirely leaves the orphaned hand-off unfixed.
                if (!hasStruct && d.link !== `multicause`) { adoptionDelta -= 4; }

                summaryKey = (hasStruct && hasProcess && stats.families >= 2 && d.link === `multicause`) ? `sum_r2_good` : (peopleOnly ? `sum_r2_people` : `sum_r2_weak`);
            } else if (round === 3) {
                // Sequence under budget (Common Errors 2 & 4).
                switch (d.sequence) {
                    case `structurefirst`: adoptionDelta += 10; sustainDelta += 7; coachKey = `coach_r3_structurefirst`; break;
                    case `processfirst`:   adoptionDelta -= 8; sustainDelta -= 4; paperDelta += 4; coachKey = `coach_r3_processfirst`; break;
                    case `peoplefirst`:    adoptionDelta -= 6; sustainDelta -= 3; coachKey = `coach_r3_peoplefirst`; break;
                    case `allatonce`:      adoptionDelta -= 10; sustainDelta -= 6; paperDelta += 6; coachKey = `coach_r3_allatonce`; break;
                }

                // Change-management / communication wrap drives buy-in across every lever.
                spend += d.change;
                if (d.change >= 100) { adoptionDelta += 8; sustainDelta += 5; }
                else if (d.change >= 40) { adoptionDelta += 4; sustainDelta += 2; }
                else { adoptionDelta -= 6; coachKey = `coach_r3_nochange`; }

                // Leading indicators + named owners are the engine of a durable, sequenced plan.
                switch (d.indicators) {
                    case `leadingowners`: sustainDelta += 8; adoptionDelta += 3; if (d.sequence === `structurefirst`) coachKey = `coach_r3_disciplined`; break;
                    case `laggingonly`:   sustainDelta += 1; break;
                    case `none`:          sustainDelta -= 8; paperDelta += 3; coachKey = `coach_r3_noindicators`; break;
                }

                // Mid-plan shock: hold the sequence and absorb cost, vs add a fifth lever (Error 4) or freeze.
                switch (d.shock) {
                    case `protect`:  adoptionDelta += 5; sustainDelta += 5; break;
                    case `addlever`: adoptionDelta -= 8; sustainDelta -= 4; spend += 250; coachKey = `coach_r3_addlever`; break;
                    case `freeze`:   adoptionDelta -= 6; sustainDelta -= 6; coachKey = `coach_r3_freeze`; break;
                }

                summaryKey = (d.sequence === `structurefirst` && d.change >= 100 && d.indicators === `leadingowners`) ? `sum_r3_good` : (d.sequence === `allatonce` || d.shock === `addlever` ? `sum_r3_thin` : `sum_r3_weak`);
            } else if (round === 4) {
                // Adoption, refreeze & defend to the CEO (Common Error 5).
                switch (d.adoption) {
                    case `involve`: adoptionDelta += 11; sustainDelta += 5; coachKey = `coach_r4_involve`; break;
                    case `mandate`: adoptionDelta -= 8; paperDelta += 12; sustainDelta -= 6; coachKey = `coach_r4_mandate`; break;
                    case `email`:   adoptionDelta -= 10; paperDelta += 4; coachKey = `coach_r4_email`; break;
                }

                // Refreeze — embedding into JDs, the ERP and incentives is what sustains the gain.
                switch (d.refreeze) {
                    case `embed`:    sustainDelta += 13; adoptionDelta += 3; break;
                    case `momentum`: sustainDelta -= 12; coachKey = `coach_r4_momentum`; break;
                    case `repeat`:   sustainDelta -= 4; coachKey = `coach_r4_repeat`; break;
                }

                // The CEO's challenge: real adoption vs a paper number defended as retained revenue.
                switch (d.ceo) {
                    case `honest`:  adoptionDelta += 8; sustainDelta += 5; if (d.refreeze === `embed`) coachKey = `coach_r4_honest`; break;
                    case `coerce`:  paperDelta += 14; adoptionDelta -= 8; sustainDelta -= 8; coachKey = `coach_r4_coerce`; break;
                    case `declare`: paperDelta += 8; sustainDelta -= 10; coachKey = `coach_r4_declare`; break;
                }

                // Conviction nudges adoption.
                adoptionDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.adoption === `involve` && d.refreeze === `embed` && d.ceo === `honest`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            if (ds.budgetUsed > this.BUDGET_CAP) {
                // The budget cap bites: overspend starves the change wrap and destabilises the unit.
                ds.overBudget = true;
                const over = ds.budgetUsed - this.BUDGET_CAP;
                adoptionDelta -= Math.min(14, Math.round(over / 60));
                sustainDelta -= Math.min(10, Math.round(over / 90));
                if (round >= 2) coachKey = `coach_overbudget`;
            }

            // Adoption (genuine buy-in) and sustainability move on their deltas.
            ds.adoption = Math.max(0, Math.min(100, ds.adoption + adoptionDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustainDelta));

            // Service Recovery is driven by genuine adoption PLUS any coerced/paper gains.
            // Paper gains lift the headline but not real buy-in — and they erode sustainability.
            const adoptionGain = Math.max(0, adoptionDelta) * 0.62;
            const paperGain = paperDelta * 0.70;
            const recoveryDelta = adoptionGain + paperGain + Math.min(0, adoptionDelta) * 0.45;
            ds.recovery = Math.max(0, Math.min(100, ds.recovery + recoveryDelta));

            // Flag paper compliance: headline recovery rising while genuine adoption lags badly.
            if (paperDelta >= 8 && ds.adoption < ds.recovery - 20) ds.paperCompliance = true;

            // Revenue retained tracks genuine recovery, discounted heavily when it is only paper-deep.
            const realFactor = Math.max(0.25, Math.min(1, ds.adoption / Math.max(1, ds.recovery)));
            ds.revenueRetained = Math.round(this.REVENUE_AT_RISK * Math.min(1, ds.recovery / this.STRETCH_RECOVERY) * realFactor);

            ds.recoveryHistory.push(Math.round(ds.recovery));
            ds.adoptionHistory.push(Math.round(ds.adoption));
            ds.sustainHistory.push(Math.round(ds.sustain));

            if (round === this.ROUNDS.length && ds.recovery < this.TARGET_RECOVERY) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                recovery: Math.round(ds.recovery),
                recoveryDelta: Math.round(recoveryDelta),
                adoption: Math.round(ds.adoption),
                adoptionDelta: Math.round(adoptionDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustainDelta),
                budgetUsed: ds.budgetUsed,
                revenueRetained: ds.revenueRetained,
                paperCompliance: ds.paperCompliance,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

