        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const recovery = Math.round(ds.recovery);
            const adoption = Math.round(ds.adoption);
            const sustain = Math.round(ds.sustain);
            const composite = Math.round(Math.min(100, recovery) * 0.35 + adoption * 0.35 + sustain * 0.30);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.hitTarget && s.realAdoption);
            const badge = met
                ? `<span class="odsim-cm-badge odsim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="odsim-cm-badge odsim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = s.paper
                ? ` <span class="odsim-cm-badge odsim-cm-no">` + T(`cm_paper`) + `</span>`
                : (s.overBudget ? ` <span class="odsim-cm-badge odsim-cm-no">` + T(`cm_overbudget`) + `</span>`
                : (!s.hitTarget ? ` <span class="odsim-cm-badge odsim-cm-no">` + T(`cm_missed`) + `</span>` : ``));
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const revStr = (typeof s.revenue === `number`) ? `$` + Math.round(s.revenue) + `M` : String(s.revenue || ``);
            const metrics = ``
                + `<div class="odsim-cm-metric"><span class="odsim-cm-mv">` + Math.round(s.recovery || 0) + `</span><span class="odsim-cm-ml">` + T(`cm_m_recovery`) + `</span></div>`
                + `<div class="odsim-cm-metric"><span class="odsim-cm-mv">` + Math.round(s.adoption || 0) + `</span><span class="odsim-cm-ml">` + T(`cm_m_adoption`) + `</span></div>`
                + `<div class="odsim-cm-metric"><span class="odsim-cm-mv">` + Math.round(s.sustain || 0) + `</span><span class="odsim-cm-ml">` + T(`cm_m_sustain`) + `</span></div>`
                + `<div class="odsim-cm-metric"><span class="odsim-cm-mv">` + revStr + `</span><span class="odsim-cm-ml">` + T(`cm_m_revenue`) + `</span></div>`;
            return ``
                + `<div class="odsim-completion">`
                +   `<div class="odsim-cm-head">`
                +     `<div class="odsim-cm-score">` + score + `<span class="odsim-cm-score-max">/100</span></div>`
                +     `<div class="odsim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="odsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="odsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="odsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const recovery = Math.round(ds.recovery);
            const adoption = Math.round(ds.adoption);
            const sustain = Math.round(ds.sustain);
            const revenue = Math.round(ds.revenueRetained);

            const hitTarget = recovery >= this.TARGET_RECOVERY;
            const realAdoption = adoption >= 60 && sustain >= 55;
            const paper = ds.paperCompliance || (hitTarget && adoption < 45);
            const composite = Math.round(Math.min(100, recovery) * 0.35 + adoption * 0.35 + sustain * 0.30);

            let performanceKey = `grade_topdown`;
            if (hitTarget && realAdoption && composite >= 72) performanceKey = `grade_closed`;
            else if (hitTarget && realAdoption) performanceKey = `grade_credible`;
            else if (hitTarget && paper) performanceKey = `grade_paper`;
            else if (hitTarget) performanceKey = `grade_thin`;
            else if (recovery > this.START_RECOVERY + 18) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && realAdoption) insights.push(window.mySimulation.t(`insight_embedded`));
            else if (hitTarget && paper) insights.push(window.mySimulation.t(`insight_paper`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (sustain < 45) insights.push(window.mySimulation.t(`insight_decay`));
            if (adoption < 45) insights.push(window.mySimulation.t(`insight_lowadoption`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (recovery >= this.STRETCH_RECOVERY) insights.push(window.mySimulation.t(`insight_stretch`));
            if (hitTarget && realAdoption && sustain >= 60) insights.push(window.mySimulation.t(`insight_lasts`));

            return {
                recovery: recovery,
                adoption: adoption,
                sustain: sustain,
                revenue: revenue,
                hitTarget: hitTarget,
                realAdoption: realAdoption,
                paper: paper,
                overBudget: ds.overBudget,
                targetMissed: ds.targetMissed,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.paperCompliance) return window.mySimulation.t(`hint_paper`);
            if (ds.sustain < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sustain`);
            if (ds.adoption < 35) return window.mySimulation.t(`hint_adoption`);
            if (state.currentPeriod >= 3 && ds.recovery < 48) return window.mySimulation.t(`hint_behind`);
            if (ds.recovery >= this.TARGET_RECOVERY && ds.adoption >= 60 && ds.sustain >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

